{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/lab",
  "data": {
    "name": "LineClamp",
    "displayName": "Line Clamp",
    "category": "Layout",
    "keywords": [
      "clamp",
      "truncate",
      "ellipsis",
      "overflow",
      "lines",
      "multiline",
      "text"
    ],
    "props": [
      {
        "name": "children",
        "type": "ReactNode",
        "description": "Content to clamp: mixed inline content, nested elements, anything you would rather not wrap in a single Text.",
        "required": true
      },
      {
        "name": "maxLines",
        "type": "number",
        "description": "Maximum number of lines to show before clamping with an ellipsis.",
        "required": true
      },
      {
        "name": "hasTruncateTooltip",
        "type": "boolean",
        "description": "Show a tooltip with the full text content on hover or keyboard focus when clamped. A clamped root is focusable (tabindex 0) so keyboard users can reach the tooltip; a tabIndex you pass wins. The tooltip props follow Text's: when Text's hasTruncateTooltip is renamed in a minor, LineClamp follows.",
        "default": "true"
      },
      {
        "name": "truncateTooltipPlacement",
        "type": "'above' | 'below' | 'start' | 'end'",
        "description": "Where the truncation tooltip opens.",
        "default": "'above'"
      },
      {
        "name": "as",
        "type": "'div' | 'span' | 'p'",
        "description": "HTML element to render.",
        "default": "'div'"
      }
    ],
    "usage": {
      "description": "Clamps arbitrary content to a fixed number of lines with an ellipsis. Text's maxLines clamps a Text element; LineClamp clamps whatever it wraps and adds no typography of its own, so it suits mixed inline content and nested elements without changing their font, color or wrapping. Truncation detection reuses useTruncation (the same hook Text uses), so overflow is measured correctly even while -webkit-line-clamp clips scrollHeight.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Use LineClamp when clamping a block of mixed or composed content (not a single Text node)."
        },
        {
          "guidance": true,
          "description": "Use Text's own maxLines prop when clamping a single Text node — no need to wrap it in LineClamp."
        },
        {
          "guidance": true,
          "description": "Disable the tooltip (hasTruncateTooltip={false}) when the clamped content is already reachable elsewhere on the page, to avoid a redundant announcement."
        },
        {
          "guidance": true,
          "description": "LineClamp makes a focusable descendant inert only when both hold: (1) it is in the clamp's own flow. A positioned element is in that flow when its containing block is an element inside the clamp that is itself in the flow, as a control's own positioned wrapper is; the line test then applies to that containing block's box. A fixed element, an absolute element whose containing block is the clamp itself or lies outside it, a top-layer element (a popover or dialog), and anything rendered elsewhere through a portal each start a subtree that is never made inert, at any depth. (2) its box lies wholly beyond the clamp's last visible line. A control any part of which is visible stays reachable. A focusable with no box when LineClamp checks is treated as beyond the last line until it gains a box; LineClamp re-checks then. LineClamp re-checks when its size, its content or its fonts change. Gap: an absolutely placed control that the clamp itself clips stays a tab stop; the author owns positioned content inside a clamp. Inert takes such a control out of the Tab order and the accessibility tree. LineClamp never rewrites your own tabIndex or aria-hidden, and the element that holds focus is never made inert."
        }
      ]
    },
    "package": "@astryxdesign/lab",
    "import": "@astryxdesign/lab",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
